"use client";

import * as React from "react";
import { AlertDialog as AlertDialogPrimitive } from "radix-ui";

import { usePortalContainer } from "../scope";
import { EmptySurface } from "./empty";
import { Button } from "./button";
import { Icon, type IconSource } from "./icon";
import { Input } from "./input";

import { FrameScope } from "../lib/frame-context";
import { OverlayPendingContext, useDismissGuard, useOverlayPending } from "../lib/overlay-pending";
import { splitOverlaySections } from "../lib/overlay-sections";
import { useToastFooterReserve } from "../lib/toast-footer-reserve";
import { useOwnedEscape } from "../lib/use-owned-escape";
import { cn } from "../lib/utils";

import overlay from "./overlay.module.css";

const OpeningContext = React.createContext<{
  current: () => number;
  close: (opening: number) => void;
}>({ current: () => 0, close: () => {} });
const ConfirmContext = React.createContext<{ ready: boolean }>({ ready: true });
const PendingClaimContext = React.createContext<(delta: number) => void>(() => {});
const ToneContext = React.createContext<{
  tone?: "danger" | "neutral";
  claimMedia: (claimed: boolean) => void;
}>({ claimMedia: () => {} });

function AlertDialog({
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Root>) {
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen);
  const setOpen = React.useCallback(
    (next: boolean) => {
      if (openProp === undefined) setUncontrolledOpen(next);
      onOpenChange?.(next);
    },
    [openProp, onOpenChange]
  );
  const open = openProp ?? uncontrolledOpen;
  const openRef = React.useRef(open);
  const openingRef = React.useRef(0);
  const setOpenRef = React.useRef(setOpen);
  React.useLayoutEffect(() => {
    openRef.current = open;
    setOpenRef.current = setOpen;
  });
  React.useLayoutEffect(() => {
    if (open) openingRef.current += 1;
  }, [open]);
  const opening = React.useMemo(
    () => ({
      current: () => openingRef.current,
      close: (started: number) => {
        if (openRef.current && openingRef.current === started) setOpenRef.current(false);
      }
    }),
    []
  );
  return (
    <OpeningContext value={opening}>
      <AlertDialogPrimitive.Root
        data-slot="alert-dialog"
        open={open}
        onOpenChange={setOpen}
        {...props}
      />
    </OpeningContext>
  );
}

function AlertDialogTrigger({
  ref,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Trigger>) {
  return <AlertDialogPrimitive.Trigger ref={ref} data-slot="alert-dialog-trigger" {...props} />;
}
AlertDialogTrigger.displayName = "AlertDialogTrigger";

function AlertDialogPortal({
  children,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Portal>) {
  return (
    <AlertDialogPrimitive.Portal
      container={usePortalContainer()}
      data-slot="alert-dialog-portal"
      {...props}
    >
      <FrameScope framed={false}>
        <EmptySurface>{children}</EmptySurface>
      </FrameScope>
    </AlertDialogPrimitive.Portal>
  );
}

function AlertDialogOverlay({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Overlay>) {
  return (
    <AlertDialogPrimitive.Overlay
      ref={ref}
      data-slot="alert-dialog-overlay"
      className={cn("z-50", overlay.scrim, className)}
      {...props}
    />
  );
}
AlertDialogOverlay.displayName = "AlertDialogOverlay";

function AlertDialogContent({
  className,
  size = "default",
  tone,
  icon,
  confirmText,
  pending = false,
  onEscapeKeyDown,
  children,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Content> & {
  size?: "default" | "sm";
  /** danger shows a bad-tone lead tile (trash unless icon or AlertDialogMedia is given); neutral and unset show no automatic tile. */
  tone?: "danger" | "neutral";
  icon?: IconSource;
  /** The exact text the person types before the action enables. */
  confirmText?: string;
  /** While true, Escape and Cancel are blocked, so an in-flight action cannot be abandoned. An AlertDialogAction with loading sets this for you. */
  pending?: boolean;
} & { ref?: React.Ref<React.ComponentRef<typeof AlertDialogPrimitive.Content>> }) {
  const escape = useOwnedEscape(ref, onEscapeKeyDown);
  const [loadingActions, setLoadingActions] = React.useState(0);
  const claimPending = React.useCallback(
    (delta: number) => setLoadingActions((count) => count + delta),
    []
  );
  const busy = pending || loadingActions > 0;
  const guard = useDismissGuard(busy, { onEscapeKeyDown: escape.onEscapeKeyDown });
  const [typed, setTyped] = React.useState("");
  const [hasMedia, setHasMedia] = React.useState(false);
  const toneValue = React.useMemo(() => ({ tone, claimMedia: setHasMedia }), [tone]);
  const fieldId = React.useId();
  const field = confirmText !== undefined && (
    <div key="confirm-field" data-slot="alert-dialog-confirm" className="flex flex-col gap-1.5">
      <label htmlFor={fieldId} className="text-sm">
        Type <code className="font-mono">{confirmText}</code> to confirm
      </label>
      <Input
        id={fieldId}
        mono
        autoFocus
        autoComplete="off"
        spellCheck={false}
        value={typed}
        onChange={(event) => setTyped(event.target.value)}
        onKeyDown={(event) => {
          if (event.key !== "Enter" || event.nativeEvent.isComposing || event.keyCode === 229)
            return;
          event.preventDefault();
          if (busy || typed !== confirmText) return;
          event.currentTarget
            .closest("[data-slot=alert-dialog-content]")
            ?.querySelector<HTMLElement>("[data-slot=alert-dialog-action]")
            ?.click();
        }}
      />
    </div>
  );
  const parts = React.Children.toArray(children);
  const footerAt = parts.findIndex(
    (child) => React.isValidElement(child) && child.type === AlertDialogFooter
  );
  if (field) parts.splice(footerAt < 0 ? parts.length : footerAt, 0, field);
  const sections = splitOverlaySections(
    [
      !hasMedia && (icon || tone === "danger") && (
        <AlertDialogMedia key="auto-media" data-auto="">
          <Icon icon={icon ?? "trash"} size={20} />
        </AlertDialogMedia>
      ),
      ...parts
    ],
    { header: AlertDialogHeader, footer: AlertDialogFooter }
  );
  return (
    <AlertDialogPortal>
      <AlertDialogOverlay />
      <AlertDialogPrimitive.Content
        ref={escape.ref}
        data-slot="alert-dialog-content"
        data-sections={sections ? "" : undefined}
        data-size={size}
        data-tone={tone}
        aria-busy={busy || undefined}
        className={cn(
          "group/alert-dialog-content z-50 data-[size=default]:max-w-xs data-[size=sm]:max-w-xs data-[size=default]:sm:max-w-sm",
          overlay.pop,
          overlay.dialog,
          className
        )}
        {...props}
        onOpenAutoFocus={(event) => {
          props.onOpenAutoFocus?.(event);
          if (confirmText === undefined || event.defaultPrevented) return;
          setTyped("");
          event.preventDefault();
          document.getElementById(fieldId)?.focus();
        }}
        onEscapeKeyDown={guard.onEscapeKeyDown}
      >
        <OverlayPendingContext value={busy}>
          <PendingClaimContext value={claimPending}>
            <ConfirmContext value={{ ready: confirmText === undefined || typed === confirmText }}>
              <ToneContext value={toneValue}>
                {sections ? (
                  <>
                    {sections.scroll.length > 0 && (
                      <div
                        data-slot="alert-dialog-scroll"
                        data-scroll-fade="y"
                        data-before-footer={sections.footer.length > 0 || undefined}
                      >
                        {sections.scroll}
                      </div>
                    )}
                    {sections.footer}
                  </>
                ) : (
                  <div data-slot="overlay-scroll" data-scroll-fade="y">
                    {!hasMedia && (icon || tone === "danger") && (
                      <AlertDialogMedia data-auto="">
                        <Icon icon={icon ?? "trash"} size={20} />
                      </AlertDialogMedia>
                    )}
                    {parts}
                  </div>
                )}
              </ToneContext>
            </ConfirmContext>
          </PendingClaimContext>
        </OverlayPendingContext>
      </AlertDialogPrimitive.Content>
    </AlertDialogPortal>
  );
}
AlertDialogContent.displayName = "AlertDialogContent";

function AlertDialogHeader({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="alert-dialog-header"
      className={cn("flex flex-col gap-1.5 text-left", className)}
      {...props}
    />
  );
}
AlertDialogHeader.displayName = "AlertDialogHeader";

function AlertDialogFooter({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={useToastFooterReserve(ref)}
      data-slot="alert-dialog-footer"
      className={cn(
        "flex flex-col-reverse group-data-[size=sm]/alert-dialog-content:grid group-data-[size=sm]/alert-dialog-content:grid-cols-2 sm:flex-row sm:justify-end",
        className
      )}
      {...props}
    />
  );
}
AlertDialogFooter.displayName = "AlertDialogFooter";

function AlertDialogMedia({ className, ref, ...props }: React.ComponentProps<"div">) {
  const { tone, claimMedia } = React.useContext(ToneContext);
  const auto = (props as { "data-auto"?: string })["data-auto"] !== undefined;
  React.useLayoutEffect(() => {
    if (auto) return undefined;
    claimMedia(true);
    return () => claimMedia(false);
  }, [auto, claimMedia]);
  return (
    <div
      ref={ref}
      data-slot="alert-dialog-media"
      data-tone={tone ?? "neutral"}
      className={cn(
        "inline-flex size-10 shrink-0 items-center justify-center *:[svg:not([class*='size-'])]:size-5",
        className
      )}
      {...props}
    />
  );
}
AlertDialogMedia.displayName = "AlertDialogMedia";

function AlertDialogTitle({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Title>) {
  return (
    <AlertDialogPrimitive.Title
      ref={ref}
      data-slot="alert-dialog-title"
      className={cn("", className)}
      {...props}
    />
  );
}
AlertDialogTitle.displayName = "AlertDialogTitle";

function AlertDialogDescription({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof AlertDialogPrimitive.Description>) {
  return (
    <AlertDialogPrimitive.Description
      ref={ref}
      data-slot="alert-dialog-description"
      className={cn(
        "text-muted-foreground text-balance md:text-pretty *:[a]:underline *:[a]:underline-offset-3 *:[a]:hover:text-foreground",
        className
      )}
      {...props}
    />
  );
}
AlertDialogDescription.displayName = "AlertDialogDescription";

function AlertDialogAction({
  className,
  variant = "default",
  size = "default",
  asChild,
  disabled,
  loading,
  onClick,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Action> &
  Pick<React.ComponentPropsWithoutRef<typeof Button>, "variant" | "size"> & {
    /** Button's loading: the spinner takes the label's place at the same width and the action stays focusable but cannot fire again. With asChild the composed child gets the same guard, aria-busy and aria-disabled; pass loading to the child too for the spinner. While true, the dialog is pending (Escape and Cancel blocked). Passing loading at all, even false, means the host closes the dialog: a click runs onClick and does not close it. Without loading, an onClick that returns a Promise is loading until it settles: the dialog closes when it resolves, unless onClick called preventDefault or the dialog was closed or reopened meanwhile, and stays open when it rejects. */
    loading?: boolean;
    ref?: React.Ref<React.ComponentRef<typeof AlertDialogPrimitive.Action>>;
  }) {
  const { ready } = React.useContext(ConfirmContext);
  const claimPending = React.useContext(PendingClaimContext);
  const opening = React.useContext(OpeningContext);
  const [settling, setSettling] = React.useState(false);
  const busy = loading ?? settling;
  React.useLayoutEffect(() => {
    if (!busy) return undefined;
    claimPending(1);
    return () => claimPending(-1);
  }, [busy, claimPending]);
  const handleClick: React.MouseEventHandler<HTMLButtonElement> = (event) => {
    if (loading !== undefined || settling) {
      event.preventDefault();
      if (!busy) onClick?.(event);
      return;
    }
    const started = opening.current();
    const result: unknown = onClick?.(event);
    if (!(result instanceof Promise)) return;
    const hostKeepsOpen = event.defaultPrevented;
    event.preventDefault();
    setSettling(true);
    result.then(
      () => {
        setSettling(false);
        if (!hostKeepsOpen) opening.close(started);
      },
      (error: unknown) => {
        setSettling(false);
        throw error;
      }
    );
  };
  if (asChild) {
    const { onClickCapture, onPointerDownCapture, onKeyDownCapture, ...rest } = props;
    const block = (event: React.SyntheticEvent) => {
      event.preventDefault();
      event.stopPropagation();
    };
    return (
      <AlertDialogPrimitive.Action
        ref={ref}
        asChild
        data-slot="alert-dialog-action"
        className={className}
        disabled={disabled || !ready}
        {...rest}
        aria-busy={busy || rest["aria-busy"] || undefined}
        aria-disabled={busy || rest["aria-disabled"] || undefined}
        onClick={handleClick}
        onClickCapture={(event) => (busy ? block(event) : onClickCapture?.(event))}
        onPointerDownCapture={(event) => (busy ? block(event) : onPointerDownCapture?.(event))}
        onKeyDownCapture={(event) =>
          busy && (event.key === "Enter" || event.key === " ")
            ? block(event)
            : onKeyDownCapture?.(event)
        }
      />
    );
  }
  return (
    <Button
      variant={variant}
      size={size}
      disabled={disabled || !ready}
      loading={loading ?? (settling || undefined)}
      asChild
    >
      <AlertDialogPrimitive.Action
        ref={ref}
        data-slot="alert-dialog-action"
        className={cn(className)}
        onClick={handleClick}
        {...props}
      />
    </Button>
  );
}
AlertDialogAction.displayName = "AlertDialogAction";

function AlertDialogCancel({
  className,
  variant = "outline",
  size = "default",
  asChild,
  disabled,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof AlertDialogPrimitive.Cancel> &
  Pick<React.ComponentPropsWithoutRef<typeof Button>, "variant" | "size"> & {
    ref?: React.Ref<React.ComponentRef<typeof AlertDialogPrimitive.Cancel>>;
  }) {
  const pending = useOverlayPending();
  if (asChild)
    return (
      <AlertDialogPrimitive.Cancel
        ref={ref}
        asChild
        data-slot="alert-dialog-cancel"
        className={className}
        disabled={disabled || pending}
        {...props}
      />
    );
  return (
    <Button variant={variant} size={size} disabled={disabled || pending} asChild>
      <AlertDialogPrimitive.Cancel
        ref={ref}
        data-slot="alert-dialog-cancel"
        className={cn(className)}
        {...props}
      />
    </Button>
  );
}
AlertDialogCancel.displayName = "AlertDialogCancel";

function DiscardChangesAlertDialog({
  open,
  onOpenChange,
  onDiscard,
  title = "Discard changes?",
  description = "Your changes will be lost.",
  onCloseAutoFocus
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onDiscard: () => void;
  title?: string;
  description?: string;
  onCloseAutoFocus?: (event: Event) => void;
}) {
  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent tone="danger" icon="alert" onCloseAutoFocus={onCloseAutoFocus}>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          <AlertDialogDescription>{description}</AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Keep editing</AlertDialogCancel>
          <AlertDialogAction variant="destructive" onClick={onDiscard}>
            Discard
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}
DiscardChangesAlertDialog.displayName = "DiscardChangesAlertDialog";

export {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogMedia,
  AlertDialogOverlay,
  AlertDialogPortal,
  AlertDialogTitle,
  AlertDialogTrigger,
  DiscardChangesAlertDialog
};

.scrim {
  position: fixed;
  inset: 0;
  background-color: var(--cipher-scrim);
}
.scrim[data-state="open"] {
  animation: fadeIn var(--cipher-duration-slow) var(--cipher-ease-fade) both;
}
.scrim[data-state="closed"] {
  animation: fadeOut var(--cipher-duration-exit-slow) var(--cipher-ease-exit) both;
}
.pop {
  box-sizing: border-box;
  background-color: var(--cipher-pop);
  color: var(--cipher-ink);
  white-space: normal;
  box-shadow:
    0 0 0 var(--cipher-size-control-border) var(--cipher-pop-line),
    var(--cipher-shadow-pop);
  outline: none;
}
.dialog > *,
.sheet > * {
  --cipher-size-measure-field: 100%;
}
.dialog {
  position: fixed;
  top: 50%;
  left: 50%;
  display: flex;
  flex-direction: column;
  width: calc(100% - 2 * var(--cipher-space-16));
  max-width: var(--cipher-size-dialog);
  max-height: calc(100dvh - 2 * var(--cipher-size-overlay-margin));
  overflow: hidden;
  translate: -50% -50%;
}
.dialog[data-size="md"] {
  max-width: var(--cipher-size-dialog-wide);
}
.dialog[data-size="lg"] {
  max-width: var(--cipher-size-dialog-lg);
}
.dialog[data-state="open"] {
  animation: dialogIn var(--cipher-duration-slow) var(--cipher-ease-spring-soft) both;
}
.dialog[data-state="closed"] {
  animation: dialogOut var(--cipher-duration-exit-slow) var(--cipher-ease-exit) both;
}
.palette {
  --cipher-palette-top: clamp(var(--cipher-space-48), 13vh, calc(3 * var(--cipher-space-48)));
  top: var(--cipher-palette-top);
  display: flex;
  flex-direction: column;
  max-width: var(--cipher-size-dialog-wide);
  max-height: calc(100dvh - var(--cipher-palette-top) - var(--cipher-space-16));
  overflow: hidden;
  translate: -50% 0;
}
.palette [cmdk-root] {
  min-height: 0;
}
.palette [data-slot="command-scroll"] {
  flex: 0 1 auto;
  min-height: 0;
}
.palette [cmdk-item] {
  min-height: var(--cipher-size-control-md);
}
.palette[data-stable-height] {
  height: min(
    var(--cipher-size-palette-height),
    calc(100dvh - var(--cipher-palette-top) - var(--cipher-space-16))
  );
}
.palette[data-stable-height] > [data-slot="overlay-scroll"] {
  flex: 1 1 auto;
  grid-template-rows: minmax(0, 1fr);
}
.palette[data-stable-height] [cmdk-root] {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
}
.palette[data-stable-height] [data-slot="command-scroll"] {
  flex: 1 1 auto;
  max-height: none;
}
.palette[data-stable-height] [cmdk-root] > [data-slot="command-empty"] {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.palette[data-stable-height]
  [cmdk-root]:has(> [data-slot="command-empty"])
  > [data-slot="command-scroll"] {
  flex: 0 0 auto;
}
.close[data-slot] {
  position: absolute;
  top: calc(
    var(--cipher-dialog-pad, var(--cipher-space-overlay-inset)) +
      (var(--cipher-type-title-line-height) - var(--cipher-size-nested-md)) / 2
  );
  inset-inline-end: calc(
    var(--cipher-dialog-pad, var(--cipher-space-overlay-inset)) -
      (var(--cipher-size-nested-md) - var(--cipher-size-icon)) / 2
  );
}
.sheet:has(
    [data-slot="sheet-header"][data-tabs="only"]:not([data-slot="sheet-view"][data-hidden] *)
  ):not(:has([data-slot="panes"][data-narrow]))
  > .close[data-slot] {
  top: calc(
    var(--cipher-space-overlay-inset) + var(--cipher-space-4) +
      (var(--cipher-size-control-default) - var(--cipher-size-nested-md)) / 2
  );
}
.sheet {
  --cipher-sheet-from: 100% 0;
  --cipher-sheet-size: var(--cipher-size-sheet-sm);
}
.sheet[data-size="md"] {
  --cipher-sheet-size: var(--cipher-size-sheet-md);
}
.sheet[data-size="lg"] {
  --cipher-sheet-size: var(--cipher-size-sheet-lg);
}
.sheet[data-size="xl"] {
  --cipher-sheet-size: var(--cipher-size-sheet-xl);
}
.sheet[data-side="left"],
.sheet[data-side="right"] {
  width: 75%;
  max-width: min(var(--cipher-sheet-size), 100vw);
  transition: max-width var(--cipher-duration-moderate) var(--cipher-ease-standard);
}
@media (width <= 512px) {
  .sheet[data-side="left"],
  .sheet[data-side="right"] {
    width: 100%;
    max-width: none;
  }
}
.sheet:not([data-has-close]):is([data-side="top"], [data-side="bottom"]) > .close[data-slot] {
  display: none;
}
@media (width > 512px) {
  .sheet:not([data-has-close]) > .close[data-slot] {
    display: none;
  }
}
.sheet[data-side="left"] {
  --cipher-sheet-from: -100% 0;
}
.sheet[data-side="top"] {
  --cipher-sheet-from: 0 -100%;
}
.sheet[data-side="bottom"] {
  --cipher-sheet-from: 0 100%;
}
.sheet[data-state="open"] {
  animation: sheetIn var(--cipher-duration-slow) var(--cipher-ease-spring-soft) both;
}
.sheet[data-state="closed"] {
  animation: sheetOut var(--cipher-duration-exit-slow) var(--cipher-ease-exit) both;
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
}
@keyframes fadeOut {
  to {
    opacity: 0;
  }
}
@keyframes dialogIn {
  from {
    opacity: 0;
    scale: 0.97;
  }
}
@keyframes dialogOut {
  to {
    opacity: 0;
    scale: 0.97;
  }
}
@keyframes sheetIn {
  from {
    translate: var(--cipher-sheet-from);
  }
}
@keyframes sheetOut {
  to {
    translate: var(--cipher-sheet-from);
  }
}
@media (prefers-reduced-motion: reduce) {
  .dialog[data-state="open"],
  .sheet[data-state="open"] {
    animation-name: fadeIn;
  }
  .dialog[data-state="closed"],
  .sheet[data-state="closed"] {
    animation-name: fadeOut;
  }
}

.views {
  display: grid;
  flex: 1 1 auto;
  min-height: 0;
}
.viewCell {
  display: flex;
  grid-area: 1 / 1;
  min-width: 0;
  min-height: 0;
}
.view {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}
.view[data-hidden] {
  visibility: hidden;
}
.viewTitleRow {
  display: flex;
  align-items: flex-start;
  gap: var(--cipher-space-8);
  min-width: 0;
  margin-inline-start: calc(-1 * var(--cipher-space-6));
}
.viewTitleRow > [data-slot="button"] {
  margin-block: calc((var(--cipher-type-title-line-height) - var(--cipher-size-nested-md)) / 2);
}
.viewTitle {
  min-width: 0;
}
.viewTrail {
  color: var(--cipher-muted);
}
.viewSlot {
  display: contents;
}
.viewFoot:not(:has(> :not(.viewSlot), > .viewSlot > *)) {
  display: none;
}
@media (prefers-reduced-motion: reduce) {
  .sheet[data-side="left"],
  .sheet[data-side="right"] {
    transition: none;
  }
}
.titleLine {
  display: flex;
  align-items: flex-start;
  gap: var(--cipher-space-8);
  min-width: 0;
}
.titleLine > :first-child {
  min-width: 0;
}
.titleBadges {
  display: inline-flex;
  flex: none;
  flex-wrap: wrap;
  min-width: 0;
  max-width: 50%;
  align-items: center;
  gap: var(--cipher-space-6);
}
.titleBadges > * {
  max-width: 100%;
}
.titleBadges::before {
  content: "";
  height: var(--cipher-type-title-line-height);
  margin-inline-end: calc(-1 * var(--cipher-space-6));
}

/* Header actions: at the end of the tab row or beside the title. HeaderActions collapses icon
   actions before the tabs scroll or the title wraps, and they never shrink. Tabs and titles shrink
   first, to half the row; their large shrink factor leaves an action that cannot collapse (no
   icon, a trigger, or a disabled reason) to truncate only after that. */
.headerRow {
  display: flex;
  align-items: flex-start;
  gap: var(--cipher-space-8);
}
.headerMain {
  display: flex;
  flex: 1 1000 auto;
  flex-direction: column;
  gap: var(--cipher-space-6);
  min-width: 50%;
}
.headerTabsRow {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
}
.headerTabsRow > :not(.headerActions) {
  flex: 1 1000 auto;
  min-width: 50%;
}
.headerActions {
  display: contents;
}
.headerRow > .headerActions > * {
  margin-block: calc((var(--cipher-type-title-line-height) - var(--cipher-action-height, 0px)) / 2);
}
.headerActions
  > [data-cipher-button]:is(
    :not(:has([data-button-icon])),
    [data-layout="trigger"],
    [data-disabled-reason]
  ) {
  flex-shrink: 1;
  min-width: 0;
}
.headerActions
  > [data-cipher-button]:is(
    :not(:has([data-button-icon])),
    [data-layout="trigger"],
    [data-disabled-reason]
  )
  > [data-press] {
  min-width: 0;
  overflow: hidden;
}
.headerActions
  > [data-cipher-button]:is(
    :not(:has([data-button-icon])),
    [data-layout="trigger"],
    [data-disabled-reason]
  )
  > [data-press]
  [data-slot="button-text"] {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
